const PEOPLE={
 'c2-caravan':['Бран. А ты, значит, тоже к Вальдену? Хорошо. Лишний человек на дороге сейчас дороже лишней лошади.','Возил муку, потом оружие, теперь людей. За людей почти никто не платит. Жена говорит, я плохой купец. Наверное, она права.'],
 'c2-captain':['Здравствуй. Капитан Эдрик. Если пришёл с жалобой на дорогу — становись в очередь. Если с письмом, давай сюда.','За стеной люди хотят спать, а не участвовать в великой войне. Моя работа — дать им хотя бы несколько часов тишины. Иногда получается.'],
 'c2-city-smith':['Грета. Руки от горна убери, обожжёшься. Теперь можешь представиться. Что чиним?','Отец ковал подковы, я мечтала делать красивые ворота. Делаю мечи. Когда кончится эта дрянь, выкую такие ворота, что весь город завидовать будет.'],
 'c2-city-innkeeper':['Заходи, я Лина. По лицу вижу: сначала еда, потом вопросы. Только кровь с сапог вытри о коврик.','Половина постояльцев не может платить. Зато один чинит крышу, другая печёт хлеб. Пока никто не свалился мне в суп, хозяйство держится.'],
 'c2-order':['Роланд, Орден Серого дозора. Не пугайся плаща: допрос устрою только если сам напросишься.','Я дал клятву защищать людей. В клятве не сказано, что защищать надо только удобных людей. Начальству это уточнение не всегда нравится.'],
 'c3-commander':['Восс, комендант. Роланд о тебе писал. Садиться не предлагаю: второй стул опять в лазарете.','Я не умею красиво обещать. Могу выдать людей, припасы и сказать, куда не стоит соваться. Если сам туда пошёл — потом не ври, что я не предупреждал.'],
 'c3-mentor':['Меня зовут Эдвин. Прежде чем начнёшь рассказывать о своих подвигах, покажи, как держишь оружие.','Люблю старательных учеников. Не люблю талантливых: те сначала спорят, а потом хромают. Сам, разумеется, в молодости был талантливым.'],
 'c3-armorer':['Новый боец? Я Хильда. Покажи оружие. Да, всё так плохо, как я и думал. Ничего, посмотрим.','Куют тут многие, чинят нормально — двое. Второй сейчас пьёт. Поэтому давай без спешки: лучше подождать у горна, чем потом лежать у лекаря.'],
 'c3-quartermaster':['За припасами? Бертольд. Сначала имя, потом список. В обратном порядке я уже выдал одному человеку шесть пайков.','Говорят, я жадный. А ты попробуй делить мешок крупы на сорок человек. Впрочем, детям я всегда досыпаю. Им про арифметику знать рано.'],
 'c3-ferryman':['Ты от Восса? Курт. Можешь звать паромщиком, только не проси перевезти тебя раньше, чем выслушаешь.','Паром строил ещё мой дед. Я его ругал, когда латал доски. Теперь думаю: вот бы мне ещё столько же продержаться.'],
 'c3-tracker':['Рейна. Чужие следы я читаю лучше чужих лиц, так что представься сам.','Курт считает меня слишком осторожной. Он же потом спрашивает, нет ли под мостками волков. Есть. Потому я и осторожная.'],
 'c3-c4-prisoner':['Постой. Ты не из их охраны? Слава… ладно, потом буду благодарить. Я Эльза.','Я думала, что могу всех вылечить. Здесь поняла: иногда сначала надо выбить дверь. С этим, надеюсь, ты мне поможешь.'],
 'c3-c5-caravan':['Эй, путник! К обозу или просто поглазеть? Я Борга. Извини, сейчас на всех рычу — лошади уже обижаются.','Тридцать лет вожу грузы. Раньше боялась налога на мосту. Теперь мечтаю встретить обычного сборщика налогов. Вот до чего дожила.'],
 'c3-c5-mayor':['Добро пожаловать. Дурн, староста. Борга прислала весть, так что кружку тебе найдём. И работу тоже, уж извини.','Не люблю пришлых. Своих, впрочем, тоже не всех люблю. Но если человек работает и не обижает соседей — место ему у нас найдётся. Уши при этом могут быть любой длины.'],
 'c3-c5-smith':['Руна. В кузнице не стой в дверях, там сквозняк. Проходи, раз уж дошёл до нас живым.','Хочу выковать часы, которые не надо заводить. Тар говорит, невозможно. Прекрасно: значит, делать буду без его советов.'],
 'c3-c5-healer':['Здравствуй! Ты с дороги? Я Сиэль. Давай сперва посмотрю, целы ли у тебя руки. Ругаться на цены будешь потом.','Верю, что солнце вернётся. Дурн называет это детской глупостью. Но цветочные горшки с южного окна почему-то не убирает.'],
 'c3-c5-engineer':['Чужое лицо. Тар, механик. Если прислал Дурн — я ничего не взрывал. Сегодня, по крайней мере.','Трубы честнее людей: если труба врёт, слышно свист. Эрна вот попробуй послушай — ни свиста, ни правды.'],
 'c3-c5-clerk':['Приказчик Эрн. У вас назначено? Нет? У меня, вообще-то, учёт. Постарайтесь покороче.','Числа не спорят и не задают вопросов. Потому я и выбрал эту работу. Люди, к сожалению, всё равно приходят.'],
 'c3-c5-witness':['Новенький? Нара. Суп в котле, ложки на столе. Хочешь понравиться поварихе — верни ложку чистой.','Кормлю людей сорок лет. Даже самых вредных. На голодный желудок они ещё вреднее — проверено лично.'],
 'c3-c5-prisoner':['Тише! Ты не охранник? Горн. Если пришёл за рудой, тут только мы.','У меня дома внучка. Я обещал показать ей настоящее небо, если хоть раз разойдутся тучи. Пока умею показывать только хорошие камни.'],
 'c3-c5-hermit':['Ну вот, опять кто-то. Вед, смотритель лесопилки. Если продаёшь чудесное зелье — я уже пил. Спина до сих пор болит.','Борга ворчит, что я один тут живу. А кто за колесом смотреть будет? Оно без меня остановится. И не надо смеяться, оно действительно без меня останавливается.']
};
function profile(n){if(PEOPLE[n.id])return PEOPLE[n.id];const id=String(n.id||n.name);let hash=0;for(const c of id)hash=(hash*31+c.charCodeAt(0))>>>0;return [
 ['Привет. Кажется, мы ещё не знакомы. Я '+n.name+'. Присаживайся, если не спешишь.','Я всё надеюсь, что когда-нибудь здесь снова будет спокойно. Соседи смеются. Ну а кто-то должен надеяться, пока они смеются.'],
 ['А ты кто будешь? Ладно, не стой на ветру. Я '+n.name+'.','Раньше всё было лучше. Кроме крыши — крыша и раньше текла. Её, кстати, никто не собирается чинить? Нет? Так я и думал.'],
 ['Здравствуй, путник. '+n.name+'. Далеко добрался? Тогда не буду мучить расспросами.','Живу от работы до работы. Пока руки целы и есть с кем разделить ужин, жаловаться грех. Но я всё равно иногда жалуюсь.']
 ][hash%3]}
export function npcDialogue(p,n,raw,close=()=>{}){let first=true;return (name,text,choices=[])=>{if(!first||name!==n.name)return raw(name,text,choices);first=false;const [hello,bio]=profile(n),key='met:'+n.id,newFace=!p.rewards.includes(key);if(newFace)p.rewards.push(key);const body=(newFace?hello+'\n\n':'')+text;
 const options=[...choices,['Давай немного поговорим',()=>raw(name,bio,[['Вернуться к разговору',()=>raw(name,body,options)],['До встречи',close]])]];if(!choices.length)options.push(['Продолжить',close]);else if(!choices.some(([label])=>/встречи|Отойти|Закрыть|позже|Не сейчас|Подготовлюсь|Подготовиться|другой раз/i.test(label)))options.push(['До встречи',close]);return raw(name,body,options)};}
